# genex.toml: low phones switch levels sooner and keep half the far copies
[render.class.mobile-low]
lod_threshold_px = 3.0
far_density = 0.5

// src/game.rs — World holds oak, tower, statue: Model; oaks: Vec<Transform>.
use genex::prelude::*;
use genex::Impostor;

pub fn wire(game: &mut Game<World>) {
    // Declared once, at reset: Live bakes one impostor a frame after its model loads.
    game.on_reset(|sim, _, _, gfx| {
        let assets = gfx.assets();
        let (wood, leaves) = (assets.model("trees/oak-wood.glb"), assets.model("trees/oak-leaves.glb"));
        // Wood and leaves switch together and bake into one card where its error allows.
        sim.world.oak = gfx.assets().compound(&[&wood, &leaves]).with_impostor(Impostor::hemi());
        // Authored levels: lod1 from 24 m, lod2 from 58 m (scale 1 at the nominal view), then a card.
        let levels = [(assets.model("buildings/tower-lod1.glb"), 24.0), (assets.model("buildings/tower-lod2.glb"), 58.0)];
        sim.world.tower = assets.model("buildings/tower.glb").with_levels(&levels).with_impostor(Impostor::hemi());
        // The landmark the player walks up to keeps its detail twice as far.
        sim.world.statue = assets.model("props/statue.glb").with_lod_bias(2.0);
    });
    game.on_draw(|sim, frame, _| {
        frame.tag("trees");
        for at in &sim.world.oaks {
            frame.model(&sim.world.oak, *at);
        }
        frame.tag("tower").model(&sim.world.tower, Transform::from_xyz(0.0, 0.0, -120.0));
        frame.tag("statue").model(&sim.world.statue, Transform::from_xyz(0.0, 0.0, -10.0));
    });
    // A model only streamed cells draw: the build bakes its card, or it keeps its last level (impostor-not-baked).
    game.impostor_bake(|gfx| gfx.assets().model("trees/pine.glb").with_impostor(Impostor::hemi()));
    // Which option, if any, was refused (it then draws whole): a check reads this, never a picture.
    game.probe("lodRefused", |sim| json!(sim.world.tower.lod_refusal().map(|code| code.wire())));
}
